import React, { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, Divider, Box, Select, MenuItem, InputLabel, FormControl,CircularProgress, Alert, TextField, FormLabel } from '@mui/material';
import { useForm, Controller } from 'react-hook-form';
import { axios } from '../../utils/axios';
import InputField from '../../components/input/inputField';
import InputGallery from '../../components/inputGallery';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import DragAndDropCategory from './DragandDropCategory';
import { useMyContext } from '../provider';

const ThemeManagementPage = () => {
  const { control, handleSubmit, setValue, getValues, watch, formState: { errors } } = useForm();
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [fetchError, setFetchError] = useState(null);
  const { adsMode } = useMyContext();

  const fetchData = async () => {
    setLoading(true);
    setFetchError(null);
    try {
      const url = adsMode === '1' ? `/module/ads/categories` : `/module/listing/categories`
      const response = await axios.get(url);
      if (response?.status === 200) {
        setCategories(response.data.data.categories);
      }
    } catch (error) {
      console.error("Error fetching categories:", error);
      setFetchError("Failed to load categories. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const fetchDataTheme = async () => {
    let url = '/module/theme/?'
    if( adsMode === '1') {
      url += '&type=ads'
    }
    try {
      const response = await axios.get(url);
      const themeData = response?.data?.data[0];

      if (themeData) {
        setValue('name', themeData.name);
        setValue('title', themeData.title);
        setValue('description', themeData.description);
        
        const selectedCategoryIds = themeData?.theme?.categories.map((cat) => cat._id);
        if(Array.isArray(selectedCategoryIds))
        setValue('categories', selectedCategoryIds);
        setValue('categorizedBy', themeData?.theme?.categorizedBy?._id || '');

        setValue('images', themeData?.theme?.images);
      }
    } catch (error) {
      console.error('Error fetching theme data:', error);
    }
  };

  useEffect(() => {
    fetchData();
    fetchDataTheme()
  }, []);

  const handleCategoriesChange = (event) => {
    const selected = event.target.value;
    const prevCategories = getValues('categories') || [];
    if(!prevCategories.includes(selected)) {
      prevCategories.push(selected);
      console.log('catgories update', prevCategories)
      setValue("categories", prevCategories);
    }
  };

  const onSelectedImg = (img) => {
      if(Array.isArray(img)) {
        // const images = getValues('images')
        setValue("images", img);
      }
  };

  const onSubmit = async (data) => {
    console.log("Form Data Submitted:", data);
    const formData = new FormData();
    formData.append("name", data.name);
    formData.append("title", data.title);
    formData.append("description", data.description);
    formData.append("categories", JSON.stringify(data.categories));
    formData.append("categorizedBy", data.categories[0]);
    const images = data.images.map((item)=>item.ImageId)
    formData.append("selectedImages", JSON.stringify(images));
  
    try {
      const method = data.name ? "put" : "post";

      const response = await axios({
        method,
        url: "/module/theme",
        data: formData,
      });

      GenerateToastConfig(response?.data?.message || "Operation successful", "success");
    } catch (error) {
      console.error("Error submitting form:", error);
      GenerateToastConfig("An error occurred while saving the theme.", "error");
    }
  };

  return (
    <>
      <Helmet>
        <title>Theme Management</title>
      </Helmet>
      <Card>
        <Box p={3}>
          <Typography variant="h5">Theme Management</Typography>
          <Divider sx={{ my: 2 }} />

          {fetchError && <Alert severity="error">{fetchError}</Alert>}

          <form onSubmit={handleSubmit(onSubmit)}>
            <Grid container spacing={2}>
              <Grid container item spacing={2} xs={12}>
                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth>
                    <FormLabel htmlFor="name">Name</FormLabel>
                    <Controller
                      name="name"
                      control={control}
                      defaultValue=""
                      rules={{ required: "Name is required" }}
                      render={({ field }) => (
                        <InputField
                          error={!!errors.name}
                          helperText={errors.name?.message}
                          {...field}
                          fullWidth
                        />
                      )}
                    />
                  </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth>
                    <FormLabel htmlFor="title">Title</FormLabel>
                    <Controller
                      name="title"
                      control={control}
                      defaultValue=""
                      rules={{ required: "Title is required" }}
                      render={({ field }) => (
                        <InputField
                          error={!!errors.title}
                          helperText={errors.title?.message}
                          {...field}
                          fullWidth
                        />
                      )}
                    />
                  </FormControl>
                </Grid>
              </Grid>


              <Grid item xs={12}>
                <Controller
                  name="description"
                  control={control}
                  defaultValue=""
                  rules={{ required: "Description is required" }}
                  render={({ field }) => (
                    <TextField label="Description" error={!!errors.description} helperText={errors.description?.message} {...field} multiline rows={4} fullWidth />
                  )}
                />
              </Grid>

              <Grid item xs={12}>
                <FormControl fullWidth error={!!errors.categories}>
                  <InputLabel>Categories</InputLabel>
                  {loading ? (
                    <CircularProgress size={24} />
                  ) : (
                        <Select
                          label="Add Categories"
                          value={''}
                          onChange={(e) => {
                            handleCategoriesChange(e);
                          }}
                        >
                          {categories.map((category) => (
                            <MenuItem key={category._id} value={category._id}>
                              {category.category}
                            </MenuItem>
                          ))}
                        </Select>
                  )}
                  {errors.categories && <Typography color="error">{errors.categories.message}</Typography>}
                </FormControl>
              </Grid>
            </Grid>

            <Grid item xs={12} mt={2}>
              <FormLabel variant="h6">Selected Categories (Drag to reorder)</FormLabel>
              <Box
                sx={{
                  display: 'flex',
                  flexDirection: 'row',
                  flexWrap: 'wrap',
                  gap: 2,
                  mt: 1,
                }}
              >
                    <DragAndDropCategory
                      data={categories}
                      control={control}
                    />
              </Box>
            </Grid>

            <div className='d-flex gap-2 w-100 mb-3 mt-4'>
              <Controller
              name="images"
              control={control}
              render={({ field }) => (
                <InputGallery
                  category="themes"
                  mode='multiple'
                  fnc={onSelectedImg}
                  selectedImages={field.value ? field?.value : []}
                  imageCount={3}
                />
              )}
              />
            </div>

            <Box mt={3} sx={{ display: "flex", justifyContent: "flex-end" }}>
              <Button type="submit" variant="contained" color="primary">
                {watch("name") ? "Update Theme" : "Create Theme"}
              </Button>
            </Box>
          </form>

        </Box>
      </Card>
    </>
  );
};

export default ThemeManagementPage;
