import React, { useMemo, useState } from 'react';
import { Controller, useFieldArray } from 'react-hook-form';
import DeleteModal from 'src/components/deleteModal/DeleteModal';
import DragItem from './DragItem';

const DragAndDropCategory = ({ data, control }) => {
    const [categoryIndex, setCategoryIndex] = useState();
    const [openDeleteModal, setOpenDeleteModal] = useState(false);

    const { fields, swap, remove } = useFieldArray({
        control, // control props comes from useForm (optional: if you are using FormProvider)
        name: `categories`, // unique name for your Field Array
    });

    const categoryMap = useMemo(()=>{
        const obj = {};
        if(Array.isArray(data)) {
            for(let i=0; i< data.length;i+=1) {
                obj[data[i]._id] = data[i];
            }
        }
        return obj;
    },[data])

    const handleDelete = (index) => {
        setCategoryIndex(index);
        setOpenDeleteModal(true);
      };

      const executeDelete = ()=> {
        remove(categoryIndex)
        setOpenDeleteModal(false);
      }

// Here we have to get values from controller because react hook form does not support flat array (array of strings)
    return (
        <>
            {fields?.map((sub, index) =>  <Controller
            key={sub.id}
              name={`categories.${index}`}
              control={control}
              render={({ field }) => (
                <DragItem index={index} category={field.value} data={categoryMap[field.value] || {}} remove={handleDelete} swap={swap} />)}
                />
            )}
<DeleteModal
        isDeleteOpen={openDeleteModal}
        handleClose={() => setOpenDeleteModal(false)}
        handleDelete={executeDelete}
      />
        </>
    );
};

export default DragAndDropCategory;
